1|import type { SessionSummary } from "@echo/contracts";
2|import {
3|  Alert02Icon,
4|  CheckmarkCircle02Icon,
5|  Clock01Icon,
6|  SkipForwardIcon,
7|} from "@hugeicons/core-free-icons";
8|import { HugeiconsIcon } from "@hugeicons/react";
9|import { memo } from "react";
10|import { Link } from "react-router";
11|import { formatTime } from "../api";
12|import { sessionDisplayTitle } from "../session-display";
13|
14|function timeAgo(iso: string | null): string {
15|  if (!iso) return "unknown time";
16|  const then = new Date(iso).getTime();
17|  if (Number.isNaN(then)) return "unknown time";
18|  const seconds = Math.max(0, Math.floor((Date.now() - then) / 1000));
19|  if (seconds < 60) return "just now";
20|  const minutes = Math.floor(seconds / 60);
21|  if (minutes < 60) return `${minutes} min ago`;
22|  const hours = Math.floor(minutes / 60);
23|  if (hours < 24) return `${hours} hr${hours === 1 ? "" : "s"} ago`;
24|  const days = Math.floor(hours / 24);
25|  if (days < 7) return `${days} day${days === 1 ? "" : "s"} ago`;
26|  return new Date(then).toLocaleDateString(undefined, { month: "short", day: "numeric" });
27|}
28|
29|function cardTitle(session: SessionSummary): string {
30|  return sessionDisplayTitle(session);
31|}
32|
33|/** Red is triage signal: five or more high-risk cards shout, smaller counts stay visible but quiet. */
34|const HIGH_RISK_LOUD_THRESHOLD = 5;
35|
36|function riskBadgeClass(highRiskCount: number): string {
37|  const base =
38|    "inline-flex items-center gap-1.5 whitespace-nowrap rounded-dusk-code px-2.5 py-1 text-xs font-semibold";
39|  if (highRiskCount >= HIGH_RISK_LOUD_THRESHOLD) return `${base} bg-dusk-fail-wash text-dusk-fail`;
40|  return `${base} bg-dusk-track text-dusk-muted`;
41|}
42|
43|/** Same badge voice as the story cards: wash fill, no border, sentence case. */
44|function checkBadgeClass(checkStatus: SessionSummary["checkStatus"]): string {
45|  const base =
46|    "inline-flex items-center gap-1.5 whitespace-nowrap rounded-dusk-code px-2.5 py-1 text-xs font-semibold";
47|  if (checkStatus === "checked") return `${base} bg-dusk-pass-wash text-dusk-pass`;
48|  return `${base} bg-dusk-track text-dusk-muted`;
49|}
50|
51|function checkLabel(checkStatus: SessionSummary["checkStatus"]): string {
52|  if (checkStatus === "checked") return "Checked";
53|  if (checkStatus === "skipped") return "Skipped";
54|  return "Not checked";
55|}
56|
57|function checkIcon(checkStatus: SessionSummary["checkStatus"]) {
58|  return checkStatus === "checked" ? CheckmarkCircle02Icon : SkipForwardIcon;
59|}
60|
61|/**
