102|export function buildNarrationMessages(facts: FactSet, sessionId: string): NarrationMessages {
103|  const head = [
104|    `prompt_version: ${STORY_PROMPT_VERSION}`,
105|    `session: ${sessionId}`,
106|    `tape events: ${facts.tapeEventCount}`,
107|    "",
108|    "Facts:",
109|  ].join("\n");
