112|  let truncated = false;
113|  if (user.length > MAX_PROMPT_CHARS) {
114|    truncated = true;
115|    const kept: string[] = [];
116|    let length = head.length;
117|    for (const block of rendered) {
118|      if (length + 1 + block.length > MAX_PROMPT_CHARS) break;
119|      kept.push(block);
120|      length += 1 + block.length;
