290|  const validation = validateStoryFacts(facts, draft);
291|  return { story: validation.story, validation };
292|}
293|
294|/** A story is stale when the tape moved past its watermark in either count
295| *  or hash. The caller (server finalization) regenerates and, unless a
296| *  completed check set shares the watermark, resets check status. */
297|export function isStoryStale(
298|  story: SessionStory,
299|  current: { eventCount: number; sha256: string },
300|): boolean {
301|  return (
302|    story.tapeWatermark.eventCount !== current.eventCount ||
303|    story.tapeWatermark.sha256 !== current.sha256
304|  );
