3|/**
4| * Skeleton summaries list up to five tape paths (`buildSkeletonStory` in
5| * `@echo/story`); on a card that reads as path soup, and every card starts
6| * the same way. Compact the known skeleton shape to its first path — the
7| * full text stays on the hover title — and leave model prose untouched.
8| * Paths never contain commas; the "and other files" overflow is filtered.
9| */
10|export function compactSessionSummary(summary: string | null): string | null {
11|  if (summary === null || !summary.startsWith(SKELETON_CHANGES_PREFIX)) return summary;
12|  const list = summary.slice(SKELETON_CHANGES_PREFIX.length).replace(/\.\s*$/, "");
13|  const [first, ...rest] = list
14|    .split(",")
15|    .map((part) => part.trim())
16|    .filter((part) => part !== "" && part !== "and other files");
17|  if (first === undefined) return summary;
18|  return rest.length === 0 ? `Prompts · changes in ${first}` : `Prompts · changes in ${first}…`;
19|}
20|
21|/**
22| * Card display title: our model narration wins; when that didn't run
23| * (skeleton fallback or nothing yet), the agent's own session title is the
24| * default. The compacted skeleton text is last resort before the
25| * recording/empty placeholders.
26| */
27|export function sessionDisplayTitle(session: {
28|  summary: string | null;
29|  summarySkeleton: boolean;
30|  title: string | null;
31|  captureState: string;
