10|/** Per-field render caps. Truncation is marked so silence never poses as
11| *  absence; the validator still checks claims against the full facts. */
12|const PROMPT_CAP = 2000;
13|const AGENT_TEXT_CAP = 1000;
14|const CODE_CAP = 4000;
15|const RUN_OUTPUT_CAP = 2000;
