22|function cap(text: string, limit: number): string {
23|  if (text.length <= limit) return text;
24|  return `${text.slice(0, limit)}…(+${text.length - limit} chars)`;
25|}
26|
27|function oneLine(text: string): string {
28|  return text.replace(/\s+/g, " ").trim();
