31|export function renderFact(fact: Fact): string {
32|  switch (fact.kind) {
33|    case "prompt":
34|      return `[${fact.id}] prompt (evt ${fact.eventId}, seq ${fact.tapeSeq}): ${cap(oneLine(fact.text), PROMPT_CAP)}`;
35|    case "agent_text":
36|      return `[${fact.id}] agent_text (evt ${fact.eventId}, seq ${fact.tapeSeq}): ${cap(oneLine(fact.text), AGENT_TEXT_CAP)}`;
37|    case "hunk": {
