44|        `[${fact.id}] hunk ${fact.hunkId} ${fact.path} ` +
45|        `old=${fact.oldStart}+${fact.oldLines} new=${fact.newStart}+${fact.newLines} ` +
46|        `added=${fact.addedLines} removed=${fact.removedLines} flags=[${flags}]${mechanical}${boost} ` +
47|        `rewrite=${fact.risk.rewriteCount}\n` +
48|        `--- added\n${cap(fact.addedText, CODE_CAP)}\n` +
49|        `--- removed\n${cap(fact.removedText, CODE_CAP)}`
50|      );
51|    }
52|    case "attempt":
53|      return (
