102|export function buildNarrationMessages(facts: FactSet, sessionId: string): NarrationMessages {
103|  const head = [
104|    `prompt_version: ${STORY_PROMPT_VERSION}`,
105|    `session: ${sessionId}`,
106|    `tape events: ${facts.tapeEventCount}`,
107|    "",
108|    "Facts:",
109|  ].join("\n");
110|  const rendered = facts.facts.map(renderFact);
111|  let user = `${head}\n${rendered.join("\n\n")}`;
112|  let truncated = false;
113|  if (user.length > MAX_PROMPT_CHARS) {
114|    truncated = true;
115|    const kept: string[] = [];
116|    let length = head.length;
117|    for (const block of rendered) {
118|      if (length + 1 + block.length > MAX_PROMPT_CHARS) break;
119|      kept.push(block);
120|      length += 1 + block.length;
