192|export function buildSkeletonStory(facts: FactSet, meta: SkeletonMeta): SkeletonResult {
193|  const hunks = hunksOf(facts);
194|  const prompts = facts.facts.filter((fact): fact is PromptFact => fact.kind === "prompt");
195|  const gaps = facts.facts.filter((fact): fact is GapFact => fact.kind === "gap");
