209|  const rankedHunks = [...behaviorHunks].sort((a, b) => {
210|    const [fa, ba, ra] = riskiness(a);
211|    const [fb, bb, rb] = riskiness(b);
212|    return fb - fa || bb - ba || rb - ra || a.hunkId.localeCompare(b.hunkId);
