353|function applyOrdering(facts: FactSet, story: SessionStory, tape: TapeEvent[]): SessionStory {
354|  const seenIds = new Set<string>();
355|  const cards = story.cards.map((card, index) => {
356|    if (seenIds.has(card.id)) return { ...card, id: `${card.id}-c${index}` };
357|    seenIds.add(card.id);
358|    return card;
359|  });
360|  const ranked = [...cards].sort(
361|    (a, b) =>
362|      Number(b.highRisk) - Number(a.highRisk) ||
363|      b.riskReasons.length - a.riskReasons.length ||
364|      a.id.localeCompare(b.id),
365|  );
366|  const rankOf = new Map(ranked.map((card, index) => [card.id, index + 1]));
367|
368|  const seqByEvent = new Map(tape.map((event) => [event.event_id, event.tape_seq]));
369|  const attemptsByPath = new Map<string, AttemptFact[]>();
370|  for (const fact of facts.facts) {
371|    if (fact.kind !== "attempt") continue;
372|    attemptsByPath.set(fact.path, [...(attemptsByPath.get(fact.path) ?? []), fact]);
373|  }
374|  const hunksById = new Map(
375|    facts.facts
376|      .filter((fact): fact is HunkFact => fact.kind === "hunk")
377|      .map((fact) => [fact.hunkId, fact]),
378|  );
379|  const eventsForToolCall = (toolCallId: string): string[] => {
380|    const ids: string[] = [];
381|    for (const fact of facts.facts) {
382|      if (fact.kind === "run" && fact.toolCallId === toolCallId) ids.push(...fact.eventIds);
383|      if (fact.kind === "attempt" && fact.toolCallId === toolCallId && fact.eventId !== null) {
384|        ids.push(fact.eventId);
385|      }
386|    }
387|    return ids;
388|  };
389|  const earliestOf = (card: ChangeCard): number => {
390|    let earliest = Number.POSITIVE_INFINITY;
391|    const consider = (eventId: string) => {
392|      const seq = seqByEvent.get(eventId);
393|      if (seq !== undefined && seq < earliest) earliest = seq;
394|    };
395|    for (const hunkId of card.constituentHunkIds) {
396|      for (const attempt of attemptsByPath.get(hunksById.get(hunkId)?.path ?? "") ?? []) {
397|        if (attempt.eventId !== null) consider(attempt.eventId);
398|      }
399|    }
400|    for (const toolCallId of card.constituentActionIds) {
401|      for (const eventId of eventsForToolCall(toolCallId)) consider(eventId);
402|    }
403|    return earliest;
404|  };
405|  const chrono = [...cards].sort((a, b) => earliestOf(a) - earliestOf(b));
406|  const orderOf = new Map(chrono.map((card, index) => [card.id, index]));
407|  return {
408|    ...story,
409|    cards: cards.map((card) => ({
410|      ...card,
411|      rank: rankOf.get(card.id) ?? card.rank,
412|      sessionOrder: orderOf.get(card.id) ?? card.sessionOrder,
413|    })),
414|  };
