417|/**
418| * Deterministic post-processing: server-owned enrichment (see enrichStory)
419| * and card ordering (see applyOrdering) run BEFORE validation so every
420| * added claim is checked like a model claim, then single-regen drop, then
421| * the server-owned blind-spot diagnostics (review + capture quality) merged
422| * without validation — they describe the pipeline, not the session.
423| */
424|export function finalizeStory(args: {
425|  facts: FactSet;
426|  draft: SessionStory;
427|  tape: TapeEvent[];
428|  reviewDiagnostics: string[];
429|  captureQuality: string;
430|}): SessionStory {
431|  const ordered = applyOrdering(args.facts, enrichStory(args.facts, args.draft), args.tape);
432|  const validation = validateStoryFacts(args.facts, ordered);
433|  const dropped = dropFailedClaims(validation);
434|  const merged = [...dropped.story.blindSpots];
435|  for (const line of args.reviewDiagnostics) {
436|    if (!merged.includes(line)) merged.push(line);
437|  }
438|  if (
439|    (args.captureQuality === "partial" || args.captureQuality === "import_only") &&
440|    !merged.includes("intermediate states may not be captured")
441|  ) {
442|    merged.push("intermediate states may not be captured");
443|  }
444|  return SessionStorySchema.parse({ ...dropped.story, blindSpots: merged });
