447|/**
448| * Whether a session story carries anything worth showing: a model narration
449| * always counts, while a deterministic skeleton only counts when it found
450| * prompts or changes (cards, asked/delivered prompts, short version).
451| * Diagnostics alone (detours, loose ends, blind spots, gaps) are not content.
452| */
453|export function storyHasContent(story: SessionStory): boolean {
454|  if (!story.skeleton) return true;
