1|import type { ChangeCard, SessionStory, StoryClaim, VerificationBadge } from "@echo/contracts";
2|import type { AttemptFact, Fact, FactSet, HunkFact, RunFact } from "./facts";
3|
4|/**
5| * Deterministic story validator (ARCHITECTURE §12, `generate_story` step 3).
6| * Checks every claim's numbers, file paths and quoted spans against the cited
7| * facts, then overwrites verification and risk from the fact set — never
8| * trusted from the model. Claims stay in place with verdicts; the server
9| * regenerates once per failed claim and calls {@link dropFailedClaims} for
10| * whatever still fails.
11| */
12|
13|export interface ClaimLocation {
14|  area: "card" | "detour" | "looseEnd" | "shortVersion" | "askVsResult" | "storyText";
15|  /** Card, detour or loose-end id; null outside those areas. */
16|  key: string | null;
17|  /** Claim field, or bare-string field name for storyText. */
18|  field: string;
19|  /** Claim index, or -1 for singular bare strings. */
20|  index: number;
21|}
22|
23|export interface ClaimVerdict {
24|  location: ClaimLocation;
