37|const NUMBER_TOKEN = /\d+/g;
38|// A path token starts with a letter (so `1.3` stays a number) and either has
39|// a dotted extension or contains a slash next to a letter (so `3/9` stays a
40|// number pair).
41|const PATH_TOKEN =
42|  /[A-Za-z@_][A-Za-z0-9_@./-]*\.[a-z0-9]{1,10}\b|[A-Za-z0-9_@.-]*[A-Za-z][A-Za-z0-9_@.-]*\/[A-Za-z0-9_@./-]+/g;
43|const QUOTE_TOKEN = /`([^`]+)`/g;
44|
45|function tokens(text: string, pattern: RegExp): string[] {
46|  pattern.lastIndex = 0;
47|  const found: string[] = [];
48|  let match = pattern.exec(text);
49|  while (match) {
50|    found.push(match[0]);
51|    match = pattern.exec(text);
52|  }
53|  return found;
54|}
55|
56|function quotesIn(text: string): string[] {
57|  QUOTE_TOKEN.lastIndex = 0;
58|  const found: string[] = [];
59|  let match = QUOTE_TOKEN.exec(text);
60|  while (match) {
61|    if (match[1]) found.push(match[1]);
62|    match = QUOTE_TOKEN.exec(text);
63|  }
64|  return found;
65|}
