67|interface FactSurface {
68|  texts: string[];
69|  numbers: Set<string>;
70|  paths: Set<string>;
71|}
72|
73|function surfaceOf(fact: Fact): FactSurface {
74|  switch (fact.kind) {
75|    case "prompt":
76|    case "agent_text":
77|      return { texts: [fact.text], numbers: new Set(), paths: new Set() };
78|    case "hunk":
79|      return {
80|        texts: [fact.path, fact.addedText, fact.removedText],
81|        numbers: new Set(
82|          [
83|            fact.oldStart,
84|            fact.oldLines,
85|            fact.newStart,
86|            fact.newLines,
87|            fact.addedLines,
88|            fact.removedLines,
89|          ].map(String),
90|        ),
91|        paths: new Set([fact.path]),
92|      };
93|    case "attempt":
94|      return {
95|        texts: [fact.path, fact.trigger, fact.status],
96|        numbers: new Set([fact.introducedLines, fact.survivingLines].map(String)),
97|        paths: new Set([fact.path]),
98|      };
99|    case "run":
100|      return {
101|        texts: fact.outputText === null ? [fact.command] : [fact.command, fact.outputText],
102|        numbers: new Set(fact.exitCode === null ? [] : [String(fact.exitCode)]),
103|        paths: new Set(),
104|      };
105|    case "action":
106|      return {
107|        texts: fact.command === null ? [fact.name] : [fact.name, fact.command],
108|        numbers: new Set(),
109|        paths: new Set(),
110|      };
111|    case "gap":
112|      return {
113|        texts: [fact.code, fact.detail],
114|        numbers: new Set(
115|          [fact.fromSequence, fact.toSequence].filter((n): n is number => n !== null).map(String),
116|        ),
117|        paths: new Set(),
118|      };
119|  }
