122|/** Evidence linkage: a cited attempt also brings its path's hunks (and vice
123| *  versa); a cited run brings its action (and vice versa). A claim citing the
124| *  edit event can then quote the hunk code it produced. */
125|function linkedFacts(cited: Fact[], all: Fact[]): Fact[] {
126|  const extra: Fact[] = [];
127|  for (const fact of cited) {
128|    if (fact.kind === "attempt" || fact.kind === "hunk") {
129|      for (const other of all) {
130|        if (
131|          (other.kind === "attempt" || other.kind === "hunk") &&
132|          other.path === fact.path &&
133|          other.id !== fact.id
134|        ) {
135|          extra.push(other);
136|        }
137|      }
138|    }
139|    if (fact.kind === "run" || fact.kind === "action") {
140|      for (const other of all) {
141|        if (
142|          (other.kind === "run" || other.kind === "action") &&
143|          other.toolCallId === fact.toolCallId &&
144|          other.id !== fact.id
145|        ) {
146|          extra.push(other);
147|        }
148|      }
149|    }
150|  }
151|  return extra;
