154|function standaloneNumber(text: string, number: string): boolean {
155|  return new RegExp(`(?:^|\\D)${number}(?=\\D|$)`).test(text);
156|}
157|
158|function checkClaim(text: string, factIds: string[], facts: FactSet): string[] {
159|  const errors: string[] = [];
160|  const byId = new Map(facts.facts.map((fact) => [fact.id, fact]));
161|  const cited: Fact[] = [];
162|  for (const id of factIds) {
163|    const fact = byId.get(id);
164|    if (!fact) errors.push(`unknown fact id ${id}`);
165|    else cited.push(fact);
166|  }
167|  const surfaceFacts = [...cited, ...linkedFacts(cited, facts.facts)];
168|  const texts = surfaceFacts.flatMap((fact) => surfaceOf(fact).texts);
169|  const numbers = new Set(surfaceFacts.flatMap((fact) => [...surfaceOf(fact).numbers]));
170|  const paths = new Set(surfaceFacts.flatMap((fact) => [...surfaceOf(fact).paths]));
171|  for (const text of texts) {
172|    for (const token of tokens(text, PATH_TOKEN)) paths.add(token);
173|  }
174|  for (const number of tokens(text, NUMBER_TOKEN)) {
175|    if (!numbers.has(number) && !texts.some((entry) => standaloneNumber(entry, number))) {
176|      errors.push(`number ${number} not in cited evidence`);
177|    }
178|  }
179|  for (const token of tokens(text, PATH_TOKEN)) {
180|    if (!paths.has(token)) errors.push(`path ${token} not in cited evidence`);
181|  }
182|  const joined = texts.join("\n");
183|  for (const quote of quotesIn(text)) {
184|    if (!joined.includes(quote))
185|      errors.push(`quote ${JSON.stringify(quote)} not in cited evidence`);
186|  }
187|  return errors;
