275|function cardVerification(
276|  card: ChangeCard,
277|  hunks: HunkFact[],
278|  attempts: AttemptFact[],
279|  passingRun: boolean,
280|  byId: Map<string, Fact>,
281|): VerificationBadge {
282|  const cited: Fact[] = [];
283|  for (const list of [card.why, card.before, card.now, card.checkedBy]) {
284|    for (const claim of list) {
285|      for (const id of claim.factIds) {
286|        const fact = byId.get(id);
287|        if (fact) cited.push(fact);
288|      }
289|    }
290|  }
291|  if (cited.length === 0) return "nothing";
292|  const behavior = cited.filter(
293|    (fact) =>
294|      fact.kind === "hunk" ||
295|      fact.kind === "attempt" ||
296|      fact.kind === "run" ||
297|      fact.kind === "action",
298|  );
299|  if (behavior.length === 0) return "agent_stated";
300|  if (
301|    attempts.length > 0 &&
302|    attempts.every((attempt) => FAILED_STATUSES.has(attempt.status)) &&
303|    !passingRun
304|  ) {
305|    return "nothing";
306|  }
307|  if (hunks.some((hunk) => hunk.risk.unverifiedBoost)) return "partly_observed";
