312|function rollUpRisk(hunks: HunkFact[]): { highRisk: boolean; riskReasons: string[] } {
313|  // High risk needs observed evidence. Blast flags and rewrite notes cite
314|  // things the tape shows; boost markers record absence (no run, no
315|  // surviving attempt, capture gap, large mechanical diff) and drive the
316|  // partly_observed badge instead — never the risk flag.
317|  const reasons: string[] = [];
318|  const seen = new Set<string>();
319|  const push = (reason: string) => {
320|    if (!seen.has(reason)) {
321|      seen.add(reason);
322|      reasons.push(reason);
323|    }
324|  };
325|  for (const hunk of hunks) {
326|    for (const flag of hunk.risk.flags) push(flag.reason);
327|    if (hunk.risk.rewriteCount > 0) {
328|      push(
329|        `rewrite: ${hunk.risk.rewriteCount} earlier attempt(s) on ${hunk.path} reverted or replaced before landing`,
330|      );
331|    }
332|  }
333|  const highRisk = hunks.some((hunk) => hunk.risk.flags.length > 0);
334|  return { highRisk, riskReasons: reasons };
