337|function knownEvents(facts: FactSet): Set<string> {
338|  const ids = new Set<string>();
339|  for (const fact of facts.facts) {
340|    if (fact.kind === "prompt" || fact.kind === "agent_text" || fact.kind === "gap")
341|      ids.add(fact.eventId);
342|    if (fact.kind === "attempt" && fact.eventId !== null) ids.add(fact.eventId);
343|    if (fact.kind === "run") for (const id of fact.eventIds) ids.add(id);
344|  }
345|  return ids;
