45|function tokens(text: string, pattern: RegExp): string[] {
46|  pattern.lastIndex = 0;
47|  const found: string[] = [];
48|  let match = pattern.exec(text);
49|  while (match) {
50|    found.push(match[0]);
51|    match = pattern.exec(text);
52|  }
53|  return found;
