const out=[];
function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(e.name==="story.json"){try{const s=JSON.parse(fs.readFileSync(p,"utf8"));out.push({len:s.summary.length,skel:s.skeleton,summary:s.summary});}catch{}}}};
walk(root);
out.sort((a,b)=>b.len-a.len);
for(const r of out.slice(0,25)) console.log(r.len, r.skel?"skel":"model", JSON.stringify(r.summary.slice(0,200)));
console.log("total stories:",out.length);
'","description":"List stored story summary lengths"}

